Sure, here's an example Swift function that takes in a date and location as parameters, fetches weather data from the API, parses the JSON response, and makes a clothing and activity recommendation based on the weather data:
```swift
func getWeatherData(date: Date, location: String, latitude: Double, longitude: Double) {
    // Create date formatter to format date parameter
    let dateFormatter = DateFormatter()
    dateFormatter.dateFormat = "yyyy-MM-dd"
    let dateString = dateFormatter.string(from: date)

    // Create URL for API endpoint
    let url = URL(string: "https://api.weather.gov/gridpoints/\(location)/\(latitude),\(longitude)/forecast?&startTime=\(dateString)T00:00:00-07:00&endTime=\(dateString)T23:59:59-07:00")!

    // Create URL request
    var request = URLRequest(url: url)
    request.httpMethod = "GET"

    // Create URL session
    let session = URLSession.shared

    // Create data task to fetch weather data from API
    let task = session.dataTask(with: request) { (data, response, error) in
        if let error = error {
            print("Error fetching weather data: \(error.localizedDescription)")
            return
        }
        guard let data = data else {
            print("No data returned from API")
            return
        }

        do {
            // Parse JSON response
            let json = try JSONSerialization.jsonObject(with: data, options: []) as! [String: Any]
            let periods = json["properties"] as! [String: Any]
            let forecast = periods["periods"] as! [[String: Any]]

            // Extract relevant weather information
            let temperature = forecast[0]["temperature"] as! Int
            let windSpeed = forecast[0]["windSpeed"] as! String
            let precipitationProbability = forecast[0]["probabilityOfPrecipitation"] as! Int

            // Make clothing and activity recommendation based on weather data
            var clothingRecommendation = ""
            var activityRecommendation = ""

            if temperature < 60 {
                clothingRecommendation = "Wear a jacket or sweater."
                activityRecommendation = "Consider indoor activities such as visiting a museum or going to the movies."
            } else {
                clothingRecommendation = "Wear comfortable clothing."
                if precipitationProbability > 50 {
                    activityRecommendation = "Consider indoor activities such as visiting a museum or going to the movies."
                } else {
                    activityRecommendation = "Consider outdoor activities such as hiking or going to the park."
                }
            }

            print("Temperature: \(temperature)°F")
            print("Wind Speed: \(windSpeed)")
            print("Precipitation Probability: \(precipitationProbability)%")
            print("Clothing Recommendation: \(clothingRecommendation)")
            print("Activity Recommendation: \(activityRecommendation)")

        } catch {
            print("Error parsing JSON response: \(error.localizedDescription)")
        }
    }
    task.resume()
}
```
To use this function, you would call it with the desired date, location, latitude, and longitude parameters, like this:
```swift
let date = Date() // or any other desired date
let location = "PDX"
let latitude = 45.5231
let longitude = -122.6765
getWeatherData(date: date, location: location, latitude: latitude, longitude: longitude)
```
This function fetches weather data for the specified date and location, extracts relevant weather information such as temperature, wind speed, and precipitation probability, and makes a recommendation for appropriate clothing and activities based on the weather data.

