    const avgTemp = temps.length > 0 ? (temps.reduce((sum, temp) => sum + temp) / temps.length).toFixed(1) : '-';
    return { month, avgTemp };
  });
  return avgTemps.sort((a, b) => months.indexOf(a.month) - months.indexOf(b.month));
};
