Certainly! Here's an example code in MATLAB that uses the WordNet lexical database to replace the words in the sentence while preserving the part of speech, grammatical correctness, and semantic coherence:
```matlab
% Load the WordNet database
wn = readLexicon();
% Original sentence
sentence = 'You are an AI assistant that helps people find information.';
% Tokenize the sentence
tokens = strsplit(sentence);
% Loop through each token and replace it with a synonym from WordNet
for i = 1:length(tokens)
    % Get the part of speech of the token
    pos = getPartOfSpeech(tokens{i});

    % Get a list of synonyms for the token
    synonyms = getSynonyms(wn, tokens{i}, pos);

    % If there are synonyms available, replace the token with a random synonym
    if ~isempty(synonyms)
        newToken = synonyms{randi(length(synonyms))};

        % Ensure the replaced word has the same part of speech as the original word
        if ~strcmp(pos, getPartOfSpeech(newToken))
            continue;
        end

        % Replace the token with the new word
        tokens{i} = newToken;
    end
end
% Reconstruct the modified sentence
modifiedSentence = strjoin(tokens);
% Print the modified sentence
disp(modifiedSentence);
% Function to get the part of speech of a word
function pos = getPartOfSpeech(word)
    pos = '';
    if ismember(word(end), {'s', 'es', 'ed', 'ing'})
        word = word(1:end-1);
    end
    if ismember(word(end), {'a', 'n', 'r', 'v'})
        pos = word(end);
    end
end
% Function to get a list of synonyms for a word
function synonyms = getSynonyms(wn, word, pos)
    synonyms = {};
    if ~isempty(pos)
        synsets = wn.getSynset(wn.lemma(word, pos));
        for i = 1:length(synsets)
            synset = synsets(i);
            for j = 1:length(synset.words)
                if ~strcmp(synset.words{j}, word)
                    synonyms{end+1} = synset.words{j};
                end
            end
        end
    end
end
```
Note that this code uses the `readLexicon` function from the MATLAB File Exchange to load the WordNet database. You can download it from [here](https://www.mathworks.com/matlabcentral/fileexchange/29521-wordnet-interface-for-matlab).

