```
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;
double mean(vector<double> data) {
    double sum = 0;
    for (int i = 0; i < data.size(); i++) {
        sum += data[i];
    }
    return sum / data.size();
}
double median(vector<double> data) {
    sort(data.begin(), data.end());
    int n = data.size();
    if (n % 2 == 0) {
        return (data[n/2 - 1] + data[n/2]) / 2;
    } else {
        return data[n/2];
    }
}
double mode(vector<double> data) {
    sort(data.begin(), data.end());
    double mode = data[0];
    int count = 1;
    int max_count = 1;
    for (int i = 1; i < data.size(); i++) {
        if (data[i] == data[i-1]) {
            count++;
        } else {
            if (count > max_count) {
                max_count = count;
                mode = data[i-1];
            }
            count = 1;
        }
    }
    if (count > max_count) {
        mode = data[data.size()-1];
    }
    return mode;
}
double stdev(vector<double> data) {
    double m = mean(data);
    double sum = 0;
    for (int i = 0; i < data.size(); i++) {
        sum += pow(data[i] - m, 2);
    }
    return sqrt(sum / (data.size() - 1));
}
int main() {
