To extract specific elements from the given XML data using Swift, we can use the `XMLParser` class provided by Apple. Here is the code to accomplish this:
```swift
import UIKit
class ViewController: UIViewController, XMLParserDelegate {
    var elementName: String = ""
    var name: String = ""
    var age: String = ""
    var people: [[String: String]] = []
    override func viewDidLoad() {
        super.viewDidLoad()
        let xmlString = """
        <data>
          <person>
            <name>John Doe</name>
            <age>30</age>
            <gender>Male</gender>
          </person>
          <person>
            <name>Jane Doe</name>
            <age>28</age>
            <gender>Female</gender>
          </person>
          <person>
            <name>Bob Smith</name>
            <age>42</age>
            <gender>Male</gender>
          </person>
        </data>
        """
        if let data = xmlString.data(using: .utf8) {
            let parser = XMLParser(data: data)
            parser.delegate = self
            parser.parse()
        }
    }
    // MARK: - XMLParserDelegate methods
    func parser(_ parser: XMLParser, didStartElement elementName: String, namespaceURI: String?, qualifiedName qName: String?, attributes attributeDict: [String : String] = [:]) {
        self.elementName = elementName
        if elementName == "person" {
            name = ""
            age = ""
        }
    }
    func parser(_ parser: XMLParser, foundCharacters string: String) {
        switch elementName {
        case "name": name += string
        case "age": age += string
        default: break
        }
    }
    func parser(_ parser: XMLParser, didEndElement elementName: String, namespaceURI: String?, qualifiedName qName: String?) {
        if elementName == "person" {
            let person = ["name": name, "age": age]
            people.append(person)
        }
    }
    func parserDidEndDocument(_ parser: XMLParser) {
        displayTable()
    }
    // MARK: - Helper methods
    func displayTable() {
        var table = "| Name | Age |\n|-----------|-----|\n"
        for person in people {
            let name = person["name"] ?? ""
            let age = person["age"] ?? ""
            table += "| \(name) | \(age) |\n"
        }
        print(table)
    }
}
```
This code defines a view controller that conforms to the `XMLParserDelegate` protocol. The `viewDidLoad` method initializes an XML string and creates an `XMLParser` object with that data. The `XMLParserDelegate` methods are then implemented to parse the XML data and extract the name and age of each person. The `parserDidEndDocument` method is called when parsing is complete, and it calls the `displayTable` method to format the data in a table using Markdown syntax. The resulting table is printed to the console.

