The Travelling Salesperson Problem is a well-known NP-hard problem, which means that there is no known algorithm that can solve it optimally in polynomial time. However, there are several heuristic-based algorithms that can provide near-optimal solutions in a reasonable amount of time. In this case, we can use a combination of constructive and iterative optimization methods to solve the problem efficiently. Here's an example Go code that accomplishes this:
```go
package main
import (
	"fmt"
	"math"
)
type Location struct {
	x float64
	y float64
}
type Node struct {
	location  Location
	demand    int
	readyTime int
	dueTime   int
	service  int
}
type Route struct {
	nodes []*Node
	cost  float64
}
func (r *Route) addNode(node *Node, distanceMatrix [][]float64) {
	if len(r.nodes) == 0 {
		r.nodes = append(r.nodes, node)
		return
	}
	lastNode := r.nodes[len(r.nodes)-1]
	r.nodes = append(r.nodes, node)
	r.cost += distanceMatrix[lastNode.demand][node.demand]
}
func (r *Route) removeNode(index int, distanceMatrix [][]float64) {
	if index == 0 {
		r.cost -= distanceMatrix[0][r.nodes[1].demand]
	} else if index == len(r.nodes)-1 {
		r.cost -= distanceMatrix[r.nodes[len(r.nodes)-2].demand][0]
	} else {
		r.cost -= distanceMatrix[r.nodes[index-1].demand][r.nodes[index+1].demand]
	}
	r.nodes = append(r.nodes[:index], r.nodes[index+1:]...)
}
func (r *Route) calculateCost(distanceMatrix [][]float64) {
	r.cost = 0
	for i := 0; i < len(r.nodes)-1; i++ {
		r.cost += distanceMatrix[r.nodes[i].demand][r.nodes[i+1].demand]
	}
	r.cost += distanceMatrix[r.nodes[len(r.nodes)-1].demand][0]
}
func (r *Route) getDemand() int {
	demand := 0
	for _, node := range r.nodes {
		demand += node.demand
	}
	return demand
}
func (r *Route) isFeasible(distanceMatrix [][]float64) bool {
	if r.getDemand() > vehicleCapacity {
		return false
	}
	elapsedTime := 0
	for i := 0; i < len(r.nodes); i++ {
		node := r.nodes[i]
		if elapsedTime < node.readyTime {
			elapsedTime = node.readyTime
		}
		elapsedTime += node.service
		if elapsedTime > node.dueTime {
			return false
		}
		if i < len(r.nodes)-1 {
			elapsedTime += int(distanceMatrix[node.demand][r.nodes[i+1].demand])
		}
	}
	return true
}
func generateInitialSolution(nodes []*Node, distanceMatrix [][]float64) []*Route {
	routes := []*Route{}
	for i := 1; i < len(nodes); i++ {
		route := &Route{}
		route.addNode(nodes[i], distanceMatrix)
		routes = append(routes, route)
	}
	return routes
}
func findNearestNode(route *Route, nodes []*Node, distanceMatrix [][]float64) int {
	minDistance := math.Inf(1)
	minIndex := -1
	for i := 1; i < len(nodes); i++ {
		if nodes[i] == nil {
			continue
		}
		if float64(nodes[i].readyTime) > route.cost {
			continue
		}
		if float64(nodes[i].dueTime) < route.cost {
			continue
		}
		if route.getDemand()+nodes[i].demand > vehicleCapacity {
			continue
		}
		distance := distanceMatrix[route.nodes[len(route.nodes)-1].demand][nodes[i].demand]
		if distance < minDistance {
			minDistance = distance
			minIndex = i
		}
	}
	return minIndex
}
func findCheapestInsertion(nodes []*Node, routes []*Route, distanceMatrix [][]float64) {
	for i := 1; i < len(nodes); i++ {
		if nodes[i] == nil {
			continue
		}
		minCost := math.Inf(1)
		minRoute := -1
		minIndex := -1
		for j := 0; j < len(routes); j++ {
			for k := 1; k < len(routes[j].nodes); k++ {
				route := routes[j]
				cost := distanceMatrix[route.nodes[k-1].demand][nodes[i].demand] + distanceMatrix[nodes[i].demand][route.nodes[k].demand] - distanceMatrix[route.nodes[k-1].demand][route.nodes[k].demand]
				if cost < minCost && route.getDemand()+nodes[i].demand <= vehicleCapacity && float64(nodes[i].readyTime) > route.cost && float64(nodes[i].dueTime) < route.cost {
					minCost = cost
					minRoute = j
					minIndex = k
				}
			}
		}
		if minRoute != -1 {
			routes[minRoute].addNode(nodes[i], distanceMatrix)
		}
	}
}
func optimizeRoutes(routes []*Route, distanceMatrix [][]float64) {
	for i := 0; i < len(routes); i++ {
		route := routes[i]
		for j := 1; j < len(route.nodes)-1; j++ {
			route.removeNode(j, distanceMatrix)
			for k := 0; k < len(routes); k++ {
