[Scala code]
import edu.stanford.nlp.pipeline._
import edu.stanford.nlp.ling.CoreAnnotations._
import java.util.Properties
val text = "The double helix structure of DNA was first discovered by Watson and Crick in 1953"
val props = new Properties()
props.setProperty("annotators", "tokenize, ssplit, pos, lemma, ner, parse, dcoref")
val pipeline = new StanfordCoreNLP(props)
val document = new Annotation(text)
pipeline.annotate(document)
val sentences = document.get(classOf[SentencesAnnotation])
for (sentence <- sentences) {
  val tokens = sentence.get(classOf[TokensAnnotation])
  for (token <- tokens) {
    val word = token.get(classOf[TextAnnotation])
    val pos = token.get(classOf[PartOfSpeechAnnotation])
    val ner = token.get(classOf[NamedEntityTagAnnotation])
    // Check for technical jargon and domain-specific terms
    if (pos == "NNP" || pos == "NNPS" || ner == "ORGANIZATION" || ner == "PERSON") {
      // This text contains technical terms or domain-specific terms, so it is scientific
      println("Scientific text")
      return
    }
  }
}
