To accomplish this task, we will need to use the URLSession API to make HTTP requests to the API endpoints and parse the JSON data into Swift objects. We will also need to implement the UITableViewDataSource and UITableViewDelegate protocols to display the data in a table view. Finally, we will implement a UISearchController to enable searching for countries by name or capital.
Here is the Swift code to accomplish these tasks:
```swift
import UIKit
class Country {
    var name: String
    var capital: String
    var population: Int

    init(name: String, capital: String, population: Int) {
        self.name = name
        self.capital = capital
        self.population = population
    }
}
class ViewController: UIViewController, UITableViewDataSource, UITableViewDelegate, UISearchResultsUpdating {

    @IBOutlet weak var tableView: UITableView!

    var countries = [Country]()
    var filteredCountries = [Country]()
    let searchController = UISearchController(searchResultsController: nil)

    override func viewDidLoad() {
        super.viewDidLoad()

        // Set up search controller
        searchController.searchResultsUpdater = self
        searchController.obscuresBackgroundDuringPresentation = false
        searchController.searchBar.placeholder = "Search Countries"
        navigationItem.searchController = searchController
        definesPresentationContext = true

        // Fetch data from API endpoints
        let group = DispatchGroup()
        group.enter()
        fetchCountries { countries in
            self.countries = countries
            group.leave()
        }
        group.enter()
        fetchCapitals { capitals in
            for (index, capital) in capitals.enumerated() {
                self.countries[index].capital = capital
            }
            group.leave()
        }
        group.enter()
        fetchPopulations { populations in
            for (index, population) in populations.enumerated() {
                self.countries[index].population = population
            }
            group.leave()
        }
        group.notify(queue: .main) {
            self.tableView.reloadData()
        }
    }

    // MARK: - Table view data source

    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        if isFiltering() {
            return filteredCountries.count
        }
        return countries.count
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "cell", for: indexPath)

        let country: Country
        if isFiltering() {
            country = filteredCountries[indexPath.row]
        } else {
            country = countries[indexPath.row]
        }

        cell.textLabel?.text = country.name
        cell.detailTextLabel?.text = "\(country.capital) • Population: \(country.population)"

        return cell
    }

    // MARK: - Search controller

    func updateSearchResults(for searchController: UISearchController) {
        filterContentForSearchText(searchController.searchBar.text!)
    }

    func filterContentForSearchText(_ searchText: String) {
        filteredCountries = countries.filter { country in
            return country.name.lowercased().contains(searchText.lowercased()) ||
                country.capital.lowercased().contains(searchText.lowercased())
        }

        tableView.reloadData()
    }

    func isFiltering() -> Bool {
        return searchController.isActive && !searchBarIsEmpty()
    }

    func searchBarIsEmpty() -> Bool {
        return searchController.searchBar.text?.isEmpty ?? true
    }

    // MARK: - API requests

    func fetchCountries(completion: @escaping ([Country]) -> Void) {
        let url = URL(string: "https://restcountries.com/v3.1/all")!
        URLSession.shared.dataTask(with: url) { data, response, error in
            guard let data = data else { return }
            do {
                let json = try JSONSerialization.jsonObject(with: data, options: []) as! [[String: Any]]
                let countries = json.map { Country(name: $0["name"]!["common"] as! String, capital: "", population: 0) }
                completion(countries)
            } catch {
                print(error)
            }
        }.resume()
    }

    func fetchCapitals(completion: @escaping ([String]) -> Void) {
        let urls = countries.map { "https://restcountries.com/v3.1/capital/\($0.name.lowercased())" }
        let group = DispatchGroup()
        var capitals = [String]()
        for url in urls {
            group.enter()
            URLSession.shared.dataTask(with: URL(string: url)!) { data, response, error in
                guard let data = data else { return }
                do {
                    let json = try JSONSerialization.jsonObject(with: data, options: []) as! [[String: Any]]
                    let capital = json[0]["name"]!["common"] as! String
                    capitals.append(capital)
                    group.leave()
                } catch {
                    print(error)
                    group.leave()
                }
            }.resume()
        }
        group.notify(queue: .main) {
            completion(capitals)
        }
    }

    func fetchPopulations(completion: @escaping ([Int]) -> Void) {
        let urls = countries.map { "https://restcountries.com/v3.1/name/\($0.name.lowercased())?fullText=true" }
        let group = DispatchGroup()
        var populations = [Int]()
        for url in urls {
            group.enter()
            URLSession.shared.dataTask(with: URL(string: url)!) { data, response, error in
                guard let data = data else { return }
                do {
                    let json = try JSONSerialization.jsonObject(with: data, options: []) as! [[String: Any]]
                    let population = json[0]["population"] as! Int
                    populations.append(population)
                    group.leave()
                } catch {
                    print(error)
                    group.leave()
                }
            }.resume()
        }
        group.notify(queue: .main) {
            completion(populations)
        }
    }

}
```
In this code, we define a `Country` class to represent the data we will be fetching from the API endpoints. We also implement the `ViewController` class, which is a subclass of `UIViewController` and conforms to the `UITableViewDataSource`, `UITableViewDelegate`, and `UISearchResultsUpdating` protocols.
In the `viewDidLoad` method, we set up a `UISearchController` and fetch data from the API endpoints using the `fetchCountries`, `fetchCapitals`, and `fetchPopulations` methods. We use a `DispatchGroup` to ensure that all three API requests have completed before reloading the table view data.
In the `tableView(_:numberOfRowsInSection:)` and `tableView(_:cellForRowAt:)` methods, we display the country data in the table view. We also implement the `UISearchResultsUpdating` protocol to filter the data based on the user's search text.
Finally, we implement the `fetchCountries`, `fetchCapitals`, and `fetchPopulations` methods to make HTTP requests to the API endpoints and parse the JSON data into Swift objects. We use a `DispatchGroup` to ensure that all API requests have completed before calling the `completion` closure with the parsed data.
